import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import toast from 'react-hot-toast';
import logo from '../assets/logo-lhm.png';

export default function LoginPage() {
  const { login } = useAuth();
  const navigate = useNavigate();
  const [form, setForm] = useState({ email: '', password: '' });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true); setError('');
    try {
      await login(form.email, form.password);
      toast.success('Bienvenue !');
      navigate('/');
    } catch (err) {
      setError(err.response?.data?.message || 'Identifiants incorrects');
    } finally {
      setLoading(false);
    }
  };

  const demoLogins = [
    { label: 'Administrateur', email: 'admin@lhm-madagascar.org', pwd: 'Admin@1234' },
    { label: 'Direction', email: 'direction@lhm-madagascar.org', pwd: 'Direction@1234' },
    { label: 'Assistant RH', email: 'rh@lhm-madagascar.org', pwd: 'RH@1234' },
    { label: 'Stock', email: 'stock@lhm-madagascar.org', pwd: 'Stock@1234' },
  ];

  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column', background: 'linear-gradient(135deg, #091628 0%, #0f2044 50%, #1a3560 100%)' }}>
      <div style={{ display: 'flex', flex: 1, flexWrap: 'wrap' }}>

        {/* Left panel */}
        <div style={{ flex: 1, minWidth: 280, display: 'flex', alignItems: 'center', justifyContent: 'center', flexDirection: 'column', padding: '40px 32px', color: 'white' }}>
          <div style={{ maxWidth: 440, width: '100%' }}>

            {/* REAL LOGO */}
            <div style={{ marginBottom: 40 }}>
              <img
                src={logo}
                alt="LHM Madagascar - Feon'ny Filazantsara"
                style={{ maxWidth: 280, width: '100%', objectFit: 'contain', filter: 'brightness(1.1)' }}
              />
            </div>

            <h2 style={{ fontFamily: "'Playfair Display', serif", fontSize: 'clamp(1.5rem, 4vw, 2.4rem)', fontWeight: 700, lineHeight: 1.2, marginBottom: 16 }}>
              Système de Gestion<br />
              <span style={{ color: '#c9a84c' }}>Intégrée</span>
            </h2>
            <p style={{ color: 'rgba(255,255,255,0.65)', lineHeight: 1.7, fontSize: '0.95rem', marginBottom: 40 }}>
              Plateforme centralisée pour la gestion du personnel, des volontaires, des stocks et des projets de l'organisation.
            </p>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
              {['👥 Personnel', '🤝 Volontaires', '📦 Stock', '🎯 Projets'].map(item => (
                <div key={item} style={{ background: 'rgba(255,255,255,0.07)', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 10, padding: '11px 14px', fontSize: '0.85rem', color: 'rgba(255,255,255,0.8)' }}>
                  {item}
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Right panel - form */}
        <div style={{ width: '100%', maxWidth: 460, background: 'white', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '40px 32px' }}>
          <div style={{ width: '100%', maxWidth: 380 }}>

            {/* Logo on mobile top */}
            <div style={{ marginBottom: 24, display: 'flex', justifyContent: 'center' }}>
              <img src={logo} alt="LHM Madagascar" style={{ height: 48, objectFit: 'contain' }} />
            </div>

            <h3 style={{ fontFamily: "'Playfair Display', serif", fontSize: '1.6rem', color: 'var(--navy)', marginBottom: 6 }}>Connexion</h3>
            <p style={{ color: 'var(--gray-500)', fontSize: '0.88rem', marginBottom: 28 }}>Entrez vos identifiants pour accéder au système.</p>

            {error && (
              <div style={{ background: '#fee2e2', border: '1px solid #fca5a5', borderRadius: 9, padding: '12px 16px', color: '#991b1b', fontSize: '0.85rem', marginBottom: 20 }}>
                ⚠️ {error}
              </div>
            )}

            <form onSubmit={handleSubmit}>
              <div style={{ marginBottom: 16 }}>
                <label>Adresse email</label>
                <input type="email" value={form.email} onChange={e => setForm({...form, email: e.target.value})} placeholder="votre@email.com" required />
              </div>
              <div style={{ marginBottom: 22 }}>
                <label>Mot de passe</label>
                <input type="password" value={form.password} onChange={e => setForm({...form, password: e.target.value})} placeholder="••••••••" required />
              </div>
              <button type="submit" disabled={loading}
                style={{ width: '100%', background: 'linear-gradient(135deg, var(--navy), #1a3a6e)', color: 'white', border: 'none', borderRadius: 10, padding: '13px', fontSize: '0.95rem', fontWeight: 600, cursor: loading ? 'not-allowed' : 'pointer', opacity: loading ? 0.8 : 1, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8 }}>
                {loading ? <><div style={{ width: 18, height: 18, border: '2px solid rgba(255,255,255,0.3)', borderTop: '2px solid white', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} /> Connexion...</> : '🔑 Se connecter'}
              </button>
            </form>

            <div style={{ marginTop: 24, padding: '14px', background: 'var(--gray-50)', borderRadius: 10, border: '1px solid var(--gray-200)' }}>
              <p style={{ fontSize: '0.72rem', color: 'var(--gray-500)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: 8 }}>Comptes de démonstration</p>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 5 }}>
                {demoLogins.map(d => (
                  <button key={d.label} type="button" onClick={() => setForm({ email: d.email, password: d.pwd })}
                    style={{ background: 'white', border: '1px solid var(--gray-200)', borderRadius: 7, padding: '7px 12px', fontSize: '0.78rem', cursor: 'pointer', textAlign: 'left', color: 'var(--navy)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <span style={{ fontWeight: 600 }}>{d.label}</span>
                    <span style={{ color: 'var(--gray-400)', fontSize: '0.7rem' }}>{d.email}</span>
                  </button>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
